extends SceneTree

func _init() -> void:
    var scene: PackedScene = load("res://scenes/Ragdoll.tscn")
    if scene == null:
        print("FAIL: could not load scene")
        quit(1)
        return
    var root: Node = scene.instantiate()
    if root == null:
        print("FAIL: could not instantiate scene")
        quit(1)
        return

    # Check root is Node2D with script
    if not (root is Node2D):
        print("FAIL: root is not Node2D")
        quit(1)
        return
    if not root.has_method("apply_impulse_to"):
        print("FAIL: missing apply_impulse_to method")
        quit(1)
        return

    # Check required parts
    var required_parts := ["Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"]
    for p in required_parts:
        var node: Node = root.get_node_or_null(NodePath(p))
        if node == null:
            print("FAIL: missing part ", p)
            quit(1)
            return
        if not (node is RigidBody2D):
            print("FAIL: ", p, " is not RigidBody2D")
            quit(1)
            return
        var rb: RigidBody2D = node
        if rb.mass <= 0.0:
            print("FAIL: ", p, " has invalid mass")
            quit(1)
            return
        var col: CollisionShape2D = rb.get_node_or_null("CollisionShape2D") as CollisionShape2D
        if col == null:
            print("FAIL: ", p, " missing CollisionShape2D")
            quit(1)
            return
        if col.shape == null:
            print("FAIL: ", p, " CollisionShape2D has no shape")
            quit(1)
            return
        var visual: Node = null
        for child in rb.get_children():
            if child is ColorRect or child is Polygon2D:
                visual = child
                break
        if visual == null:
            print("FAIL: ", p, " missing visual placeholder")
            quit(1)
            return

    # Check exactly 5 PinJoint2D nodes
    var pin_joint_count := 0
    var pin_pairs := []
    for child in root.get_children():
        if child is PinJoint2D:
            pin_joint_count += 1
            var pj: PinJoint2D = child
            var a_node: Node = pj.get_node_or_null(pj.node_a)
            var b_node: Node = pj.get_node_or_null(pj.node_b)
            if a_node == null:
                print("FAIL: pin joint ", child.name, " node_a doesn't resolve")
                quit(1)
                return
            if b_node == null:
                print("FAIL: pin joint ", child.name, " node_b doesn't resolve")
                quit(1)
                return
            var a: String = String(a_node.name)
            var b: String = String(b_node.name)
            pin_pairs.append([a, b])
            print("DEBUG: pin joint ", child.name, " connects ", a, " and ", b)

    if pin_joint_count != 5:
        print("FAIL: expected 5 PinJoint2D nodes, found ", pin_joint_count)
        quit(1)
        return

    var required_pairs := [
        ["Head", "Torso"],
        ["LeftArm", "Torso"],
        ["RightArm", "Torso"],
        ["LeftLeg", "Torso"],
        ["RightLeg", "Torso"],
    ]
    for rp in required_pairs:
        var found := false
        for pp in pin_pairs:
            if (pp[0] == rp[0] and pp[1] == rp[1]) or (pp[0] == rp[1] and pp[1] == rp[0]):
                found = true
                break
        if not found:
            print("FAIL: missing pin joint connecting ", rp)
            quit(1)
            return

    print("PASS: All checks passed")
    quit(0)
