func _init() -> void:
    process_frame.connect(_on_process_frame)

func _on_process_frame() -> void:
    if Engine.get_physics_frames() < 2:
        return

    var failures: Array[String] = []

    # Load script
    var script: GDScript = load("res://scripts/Ragdoll.gd") as GDScript
    if script == null:
        print("FAIL: script not loaded")
        quit(1)
        return

    # Check class name
    if script.get_global_name() != "Ragdoll":
        failures.append("class_name is not Ragdoll (got: " + str(script.get_global_name()) + ")")

    # Load and instantiate scene
    var scene: PackedScene = load("res://scenes/Ragdoll.tscn")
    if scene == null:
        print("FAIL: scene not loaded")
        quit(1)
        return
    var root: Node = scene.instantiate()

    # Check root is Node2D with Ragdoll script
    if not (root is Node2D):
        failures.append("root is not Node2D")

    # Check root has Ragdoll script
    if root.get_script() != script:
        failures.append("root does not have Ragdoll script")

    # Check 6 RigidBody2D parts
    var required_parts := ["Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"]
    var rigid_body_count := 0
    for child in root.get_children():
        if child is RigidBody2D:
            rigid_body_count += 1
            var rb: RigidBody2D = child
            if rb.mass <= 0.0:
                failures.append(child.name + " has invalid mass")
            var col: CollisionShape2D = rb.get_node_or_null("CollisionShape2D") as CollisionShape2D
            if col == null:
                failures.append(child.name + " missing CollisionShape2D")
            elif col.shape == null:
                failures.append(child.name + " CollisionShape2D has no shape")
            var has_visual := false
            for c in rb.get_children():
                if c is ColorRect or c is Polygon2D:
                    has_visual = true
            if not has_visual:
                failures.append(child.name + " missing visual placeholder")

    if rigid_body_count != 6:
        failures.append("expected 6 RigidBody2D, got " + str(rigid_body_count))

    # Check pin joints
    var pin_count := 0
    var pin_pairs: Array = []
    for child in root.get_children():
        if child is PinJoint2D:
            pin_count += 1
            var pj: PinJoint2D = child
            var a_node: Node = pj.get_node_or_null(pj.node_a)
            var b_node: Node = pj.get_node_or_null(pj.node_b)
            if a_node == null:
                failures.append("PinJoint " + child.name + " node_a doesn't resolve")
            elif not (a_node is RigidBody2D):
                failures.append("PinJoint " + child.name + " node_a is not RigidBody2D")
            if b_node == null:
                failures.append("PinJoint " + child.name + " node_b doesn't resolve")
            elif not (b_node is RigidBody2D):
                failures.append("PinJoint " + child.name + " node_b is not RigidBody2D")
            if a_node and b_node:
                pin_pairs.append([String(a_node.name), String(b_node.name)])

    if pin_count != 5:
        failures.append("expected 5 PinJoint2D, got " + str(pin_count))

    var required_pairs := [
        ["Head", "Torso"],
        ["LeftArm", "Torso"],
        ["RightArm", "Torso"],
        ["LeftLeg", "Torso"],
        ["RightLeg", "Torso"],
    ]
    for rp in required_pairs:
        var found := false
        for pp in pin_pairs:
            if (pp[0] == rp[0] and pp[1] == rp[1]) or (pp[0] == rp[1] and pp[1] == rp[0]):
                found = true
                break
        if not found:
            failures.append("missing pin joint " + str(rp))

    # Check methods on root
    var ragdoll: Ragdoll = root as Ragdoll
    if ragdoll == null:
        failures.append("root is not Ragdoll instance")
    else:
        # Check signal exists
        if not ragdoll.has_signal("ragdoll_collapsed"):
            failures.append("missing ragdoll_collapsed signal")

        # Check methods
        if not ragdoll.has_method("apply_impulse_to"):
            failures.append("missing apply_impulse_to method")
        if not ragdoll.has_method("freeze_all"):
            failures.append("missing freeze_all method")
        if not ragdoll.has_method("get_part"):
            failures.append("missing get_part method")
        if not ragdoll.has_method("get_average_position"):
            failures.append("missing get_average_position method")

    if failures.is_empty():
        print("ALL CHECKS PASSED")
    else:
        print("FAILURES:")
        for f in failures:
            print("  - ", f)

    quit()
